static uint32_t dash_image_zoom(int32_t dst_w,
                                int32_t dst_h,
                                int32_t src_w,
                                int32_t src_h)
{
  int32_t zoom_w = (int32_t)(((int64_t)dst_w * 256) / src_w);
  int32_t zoom_h = (int32_t)(((int64_t)dst_h * 256) / src_h);
