      if (view->hotspots[i].id == component)
        {
          selected = &view->hotspots[i];
          lv_obj_add_state(view->hotspots[i].obj, LV_STATE_CHECKED);
        }
      else
        {
          lv_obj_remove_state(view->hotspots[i].obj, LV_STATE_CHECKED);
        }
    }

  view->selected_component = component;
  dash_update_selection_box(view, NULL);
  dash_update_selection_label(view, selected != NULL ? selected->name : NULL);
  if (selected != NULL)
    {
      LVGL_APP_LOGI(HOME_VIEW_TAG, "feedback selected %s",
                    selected->name);
    }
}

static void dash_hotspot_event(lv_event_t *event)
{
  lvgl_app_home_hotspot_t *hotspot =
    (lvgl_app_home_hotspot_t *)lv_event_get_user_data(event);
  lvgl_app_page_home_view_t *view;
  lv_event_code_t code = lv_event_get_code(event);

  if (hotspot == NULL || hotspot->view == NULL ||
      (code != LV_EVENT_PRESSED && code != LV_EVENT_CLICKED))
    {
      return;
    }

  view = hotspot->view;
  if (code == LV_EVENT_PRESSED)
    {
      dash_apply_selected_component(view, hotspot->id);
      return;
    }

  if (view->cb.on_component_selected != NULL)
    {
      view->cb.on_component_selected(hotspot->id, view->user);
    }
  else
    {
      dash_apply_selected_component(view, hotspot->id);
    }
}
