#define RESOURCE_MGR_TAG "resource_mgr"

typedef struct
{
  bool used;
  lvgl_app_resource_t resource;
} lvgl_app_resource_slot_t;

static pthread_mutex_t g_resource_lock = PTHREAD_MUTEX_INITIALIZER;
static lvgl_app_resource_slot_t g_resources
  [CONFIG_LVGL_APP_FRAMEWORK_RESOURCE_MGR_MAX_RESOURCES];

static lvgl_app_resource_t *lvgl_app_resource_mgr_find(
  uint32_t id,
  lvgl_app_resource_type_t type)
{
  unsigned int i;

  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_RESOURCE_MGR_MAX_RESOURCES; i++)
    {
      if (g_resources[i].used &&
          g_resources[i].resource.id == id &&
          g_resources[i].resource.type == type)
        {
          return &g_resources[i].resource;
        }
    }

  return NULL;
}

int lvgl_app_resource_mgr_init(void)
{
  (void)pthread_mutex_lock(&g_resource_lock);
  memset(g_resources, 0, sizeof(g_resources));
  (void)pthread_mutex_unlock(&g_resource_lock);

  LVGL_APP_LOGI(RESOURCE_MGR_TAG, "initialized");
  return 0;
}

void lvgl_app_resource_mgr_deinit(void)
{
  (void)pthread_mutex_lock(&g_resource_lock);
  memset(g_resources, 0, sizeof(g_resources));
  (void)pthread_mutex_unlock(&g_resource_lock);
}

int lvgl_app_resource_mgr_register(uint32_t id,
                                   lvgl_app_resource_type_t type,
                                   const void *data)
{
  unsigned int i;

  if (id == 0 || data == NULL)
    {
      return -EINVAL;
    }

  (void)pthread_mutex_lock(&g_resource_lock);
  if (lvgl_app_resource_mgr_find(id, type) != NULL)
    {
      (void)pthread_mutex_unlock(&g_resource_lock);
      return -EEXIST;
    }

  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_RESOURCE_MGR_MAX_RESOURCES; i++)
    {
      if (!g_resources[i].used)
        {
          g_resources[i].used = true;
          g_resources[i].resource.id = id;
          g_resources[i].resource.type = type;
          g_resources[i].resource.data = data;
          g_resources[i].resource.refs = 0;
          (void)pthread_mutex_unlock(&g_resource_lock);
          return 0;
        }
    }

  (void)pthread_mutex_unlock(&g_resource_lock);
  return -ENOSPC;
}

const void *lvgl_app_resource_mgr_acquire(uint32_t id,
                                          lvgl_app_resource_type_t type)
{
  lvgl_app_resource_t *resource;
  const void *data = NULL;

  (void)pthread_mutex_lock(&g_resource_lock);
  resource = lvgl_app_resource_mgr_find(id, type);
  if (resource != NULL)
    {
      resource->refs++;
      data = resource->data;
    }
  (void)pthread_mutex_unlock(&g_resource_lock);

  return data;
}

int lvgl_app_resource_mgr_release(uint32_t id,
                                  lvgl_app_resource_type_t type)
{
  lvgl_app_resource_t *resource;

  (void)pthread_mutex_lock(&g_resource_lock);
  resource = lvgl_app_resource_mgr_find(id, type);
  if (resource == NULL || resource->refs == 0)
    {
      (void)pthread_mutex_unlock(&g_resource_lock);
      return -ENOENT;
    }

  resource->refs--;
  (void)pthread_mutex_unlock(&g_resource_lock);

  return 0;
}

unsigned int lvgl_app_resource_mgr_ref_count(uint32_t id,
                                             lvgl_app_resource_type_t type)
{
  lvgl_app_resource_t *resource;
  unsigned int refs = 0;

  (void)pthread_mutex_lock(&g_resource_lock);
  resource = lvgl_app_resource_mgr_find(id, type);
  if (resource != NULL)
    {
      refs = resource->refs;
    }
  (void)pthread_mutex_unlock(&g_resource_lock);

  return refs;
}

