#define LVGL_APP_LOGE(module, ...) \
  lvgl_app_log_write(LVGL_APP_LOG_LEVEL_ERROR, module, __VA_ARGS__)
#define LVGL_APP_LOGW(module, ...) \
  lvgl_app_log_write(LVGL_APP_LOG_LEVEL_WARN, module, __VA_ARGS__)
#define LVGL_APP_LOGI(module, ...) \
  lvgl_app_log_write(LVGL_APP_LOG_LEVEL_INFO, module, __VA_ARGS__)
#define LVGL_APP_LOGD(module, ...) \
  lvgl_app_log_write(LVGL_APP_LOG_LEVEL_DEBUG, module, __VA_ARGS__)

#endif /* LVGL_APP_LOG_H */
#include "framework/utils/lvgl_app_log.h"

#include <stdio.h>

static lvgl_app_log_level_t g_log_level =
  (lvgl_app_log_level_t)CONFIG_LVGL_APP_FRAMEWORK_UTILS_LOG_LEVEL;

static int lvgl_app_log_priority(lvgl_app_log_level_t level)
{
  switch (level)
    {
      case LVGL_APP_LOG_LEVEL_ERROR:
        return LOG_ERR;

      case LVGL_APP_LOG_LEVEL_WARN:
        return LOG_WARNING;

      case LVGL_APP_LOG_LEVEL_DEBUG:
        return LOG_DEBUG;

      case LVGL_APP_LOG_LEVEL_INFO:
      default:
        return LOG_INFO;
    }
}

void lvgl_app_log_set_level(lvgl_app_log_level_t level)
{
  g_log_level = level;
}

void lvgl_app_log_write(lvgl_app_log_level_t level,
                        const char *module,
                        const char *fmt, ...)
{
  char message[160];
  va_list ap;

  if (level > g_log_level)
    {
      return;
    }

  va_start(ap, fmt);
  (void)vsnprintf(message, sizeof(message), fmt, ap);
  va_end(ap);

  syslog(lvgl_app_log_priority(level), "[%s] %s\n",
         module != NULL ? module : "lvgl_app", message);
}

